ALTER TABLE bank_transactions ADD COLUMN statement_row_index INTEGER;
ALTER TABLE bank_transactions ADD COLUMN statement_order TEXT CHECK(statement_order IN ('ascending','descending'));
ALTER TABLE bank_transactions ADD COLUMN statement_order_provenance TEXT;
CREATE INDEX IF NOT EXISTS bank_transactions_statement_order_idx ON bank_transactions(bank_account_id, transaction_date, statement_order, statement_row_index);
CREATE TRIGGER IF NOT EXISTS bank_transactions_statement_order_immutable BEFORE UPDATE OF statement_row_index, statement_order, statement_order_provenance ON bank_transactions BEGIN SELECT RAISE(ABORT, 'bank statement source order is immutable'); END;
CREATE TRIGGER IF NOT EXISTS bank_transactions_statement_order_complete BEFORE INSERT ON bank_transactions WHEN (NEW.statement_row_index IS NULL) != (NEW.statement_order IS NULL) OR (NEW.statement_order IS NOT NULL AND (NEW.statement_row_index < 0 OR NEW.statement_order_provenance IS NULL OR length(trim(NEW.statement_order_provenance)) = 0)) BEGIN SELECT RAISE(ABORT, 'bank statement source order requires index, direction and provenance'); END;
